export fn ewma_change_detector(v:?[*]const i64,n:usize) callconv(.c) i64 {if(v==null or n<1 or n>16)return -1;const a=v.?;const count=a[0];if(count<0 or count>15 or n!=@as(usize,@intCast(count))+1)return -1;var exponent:i64=0;var numerator:i64=0;var encoded:i64=0;for(0..@intCast(count))|i|{const sample=a[i+1];if(sample < -8 or sample>8)return -1;exponent+=1;numerator+=sample*(@as(i64,1) << @intCast(exponent-1));var signal:i64=0;if(3*numerator*numerator>((@as(i64,1)<<@intCast(2*exponent))-1)){signal=if(numerator>0)1 else 2;exponent=0;numerator=0;}encoded=encoded*4+signal;}return encoded;}
